package com.moment.app;
import android.app.*;import android.appwidget.*;import android.content.*;import android.database.Cursor;import android.widget.RemoteViews;import java.text.SimpleDateFormat;import java.util.*;
public class MomentWidget extends AppWidgetProvider {
 static final String ACTION="com.moment.app.TOGGLE";
 public void onReceive(Context c,Intent i){super.onReceive(c,i);if(ACTION.equals(i.getAction())){long id=i.getLongExtra("id",-1);if(id>=0){final PendingResult result=goAsync();final Context app=c.getApplicationContext();new Thread(()->{try{new Store(app).complete(id);refresh(app);}finally{result.finish();}},"moment-widget-db").start();}}}
 public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)draw(c,m,id);}
 static void refresh(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);android.content.ComponentName n=new android.content.ComponentName(c,MomentWidget.class);for(int id:m.getAppWidgetIds(n))draw(c,m,id);}
 static void draw(Context c,AppWidgetManager m,int widgetId){RemoteViews v=new RemoteViews(c.getPackageName(),R.layout.widget);int[] views={R.id.task1,R.id.task2,R.id.task3};int index=0;try(Cursor cur=new Store(c).todayTasks(new SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()))){while(cur.moveToNext()&&index<3){long id=cur.getLong(0);int view=views[index++];v.setTextViewText(view,"☐  "+cur.getString(1));Intent i=new Intent(c,MomentWidget.class).setAction(ACTION).putExtra("id",id);PendingIntent p=PendingIntent.getBroadcast(c,(int)id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(view,p);}}for(;index<3;index++){v.setTextViewText(views[index],index==0?"No tasks due today. You’re all set!":"");v.setOnClickPendingIntent(views[index],null);}Intent open=new Intent(c,MainActivity.class).setAction("com.moment.app.QUICK_ADD");PendingIntent p=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);v.setOnClickPendingIntent(R.id.add,p);m.updateAppWidget(widgetId,v);}
}
